# 1급 CH10 가정법 (91~100) 2차 감수
X(1, 91, r="‘~이 없다면(없었다면)’은 Without이나 But for로 나타낸다. 뒤의 주절이 would/could + 동사원형이면 현재 사실의 반대, would/could have + 과거분사이면 과거 사실의 반대를 가정한다.",
  n=["‘~이 없다면’의 뜻은 But이 아니라 But for로 나타내므로", "Not for라는 표현은 쓰지 않으므로", "Because 뒤에는 절이 와야 하고 뜻도 맞지 않으므로", "‘이 번역 앱이 없다면’을 Without으로 바르게 나타냈으므로",
     "Thanks to는 ‘~ 덕분에’라는 뜻이라 뒤의 could not과 맞지 않으므로"],
  st="① 직설법 문장에서 원인({0})을 찾는다. 가정법 문장은 그 원인이 없다고 가정하고 결과를 반대로 말한다({1}). → ② ‘~이 없다면(없었다면)’은 Without이나 But for로 나타낸다. → ③ 뜻이 다르거나 쓰지 않는 표현을 지운다. 정답은 {a}.",
  R=("번역 앱이 있다", "소통할 수 없을 것이다"), B=("Jane이 경고해 주었다", "돈을 잃었을 것이다"), C=("Mina에게 비상 열쇠가 있었다", "들어갈 수 없었을 것이다"), D=("Tom이 길을 알려 주었다", "길을 잃었을 것이다"),
  E=("이 소프트웨어가 있다", "분석할 수 없을 것이다"), F=("팀에 자금이 충분하다", "계속할 수 없을 것이다"))
RV(1, 91, "BCDEF", fx=True, why="수정 예시의 발문이 고쳐진 원문항 발문(‘직설법 문장을 가정법으로 바꿀 때 빈칸에 알맞은 것을 고르시오’)과 조금 달라 같게 맞췄다.")

X(1, 92, r="가정법 과거는 ‘If + 과거형, would + 동사원형’(현재 사실의 반대), 가정법 과거완료는 ‘If + had + 과거분사, would have + 과거분사’(과거 사실의 반대)이다. 과거의 일이 현재에 영향을 줄 때는 ‘If + had + 과거분사, would + 동사원형 ~ now’(혼합가정법)를 쓴다.",
  n=["과거의 가정(had not injured)과 현재의 결과(could be ~ now)를 이은 혼합가정법이 바르므로", "가정법 과거(wore, would look)가 바르므로", "가정법 과거완료(had not believed, could not have succeeded)가 바르므로",
     "주절에 조동사의 과거형 없이 is를 썼다. the roads would be dry now로 고쳐야 하므로", "가정법 과거완료(had not slowed, would have happened)가 바르므로"],
  st="① 문장마다 if절의 동사와 주절의 동사, 그리고 주절의 시간 표현(now, yesterday 등)을 짝짓는다. → ② If + had + 과거분사 뒤의 주절은 과거의 일이면 would have + 과거분사, 지금의 일(now)이면 would + 동사원형이다. → ③ {n}은 {0}",
  R="주절에 would 없이 is를 썼으므로 틀렸다(would be dry now).", B="yesterday의 일인데 would not miss를 썼으므로 틀렸다(would not have missed).", C="yesterday의 일인데 would be를 썼으므로 틀렸다(would have been).",
  D="last week의 일인데 would pass를 썼으므로 틀렸다(would have passed).", E="last night의 일인데 would not get을 썼으므로 틀렸다(would not have gotten).", F="yesterday의 일인데 would not be를 썼으므로 틀렸다(would not have been).")

X(1, 93, r="I wish + 가정법 과거(동사의 과거형, be동사는 were)는 지금 이룰 수 없는 소망을, I wish + 가정법 과거완료(had + 과거분사)는 지난 일에 대한 아쉬움을 나타낸다. wish 뒤에 현재형을 쓰지 않는다.",
  n=["지금의 소망을 I wish + 과거형(had)으로 바르게 나타냈으므로", "가정법 과거(had, would help)가 바르므로", "지금의 소망인데 wish 뒤에 현재형 is를 썼다. were로 고쳐야 하므로", "I wish + 과거형(had)이 바르므로",
     "가정법 과거완료(would have informed, had contacted)가 바르므로"],
  st="① wish가 있는 문장은 wish 뒤 동사의 시제를 본다. 지금의 소망이면 과거형(were, had, could), 지난 일에 대한 아쉬움이면 had + 과거분사다. → ② if가 있는 문장은 if절과 주절의 시제 짝을 확인한다. → ③ {n}은 wish 뒤에 현재형({0})을 썼으므로 과거형({1})으로 고쳐야 한다.",
  R=("is", "were"), B=("is", "were"), C=("know", "knew"), D=("is", "were"), E=("can", "could"), F=("are", "were"))

X(1, 94, r="가정법 과거완료는 ‘If + had + 과거분사, would/could/might have + 과거분사’로 과거 사실의 반대를 가정한다. I wish/If only + had + 과거분사는 지난 일에 대한 아쉬움을 나타낸다.",
  n=["if절에 had been을 써서 과거 사실의 반대를 바르게 가정했으므로", "yesterday의 일이므로 would perform이 아니라 would have performed를 써야 하므로", "I wish + could have + 과거분사로 지난 일에 대한 아쉬움을 바르게 나타냈으므로",
     "If only + had + 과거분사로 지난 일에 대한 아쉬움을 바르게 나타냈으므로", "might have + 과거분사로 과거 사실의 반대를 바르게 추측했으므로"],
  st="① 대화가 지난 일({0})에 대한 것이므로 모든 밑줄이 과거 사실의 반대를 가정하는 형태여야 한다. → ② if절·wish 뒤는 had + 과거분사, 주절은 would/could/might have + 과거분사인지 확인한다. → ③ {n}만 주절에 would + 동사원형({1})을 썼다. would have + 과거분사({2})로 고쳐야 한다.",
  R=("어제의 토론 대회", "would perform", "would have performed"), B=("어젯밤 작업을 잃어버린 일", "would not lose", "would not have lost"), C=("어제 기차를 놓친 일", "would catch", "would have caught"),
  D=("지난주 경기", "would win", "would have won"), E=("어제 비를 맞은 일", "would not get", "would not have gotten"), F=("어제 시험", "would pass", "would have passed"))

X(1, 95, r="as though/as if + 가정법, If only + 가정법, But for/Without(~이 없다면), If를 생략한 도치(Were it not for ~, Had + 주어 + 과거분사)는 모두 가정법 구문이다. 과거의 일이면 had + 과거분사와 would/could have + 과거분사를 쓴다.",
  pre=["문장별 판정: A) O. as though + 가정법 과거. B) O. If only + could. C) X. yesterday가 있으므로 If he had been here로 써야 한다. D) X. yesterday가 있으므로 couldn't have finished로 써야 한다. E) O. Without ~, would be ~ now. F) O. Were it not for(= If it were not for)."],
  k="틀린 문장은 C), D) 두 개다.",
  n=["틀린 문장은 C), D) 두 개이므로"] * 5,
  st="① 문장마다 때를 알려 주는 말(yesterday, now, last week 등)과 동사 형태를 짝짓는다. 과거의 일이면 had + 과거분사와 would/could have + 과거분사가 필요하다. → ② {0} → ③ 틀린 문장을 세면 {a}이다.",
  R="C)는 yesterday의 일인데 if절에 were를 썼고, D)는 yesterday의 일인데 couldn't finish를 썼다. 나머지 네 문장은 옳다.",
  B="E)만 틀렸다. yesterday의 일인데 would pass를 썼다(would have passed). 나머지 다섯 문장은 옳다.",
  C="C)는 yesterday의 일인데 if절에 were를 썼고, F)는 가정법인데 주절에 will을 썼다(would buy). 나머지 네 문장은 옳다.",
  D="E)만 틀렸다. Had I 뒤에는 saw가 아니라 과거분사 seen이 와야 한다. 나머지 다섯 문장은 옳다.",
  E="E)는 would have 뒤에 call이 아니라 과거분사 called가 와야 하고, F)는 last week의 일인데 would fail을 썼다(would have failed). 나머지 네 문장은 옳다.",
  F="E)는 Had I 뒤에 know가 아니라 과거분사 known이 와야 하고, F)는 last week의 일인데 would fail을 썼다(would have failed). 나머지 네 문장은 옳다.")

X(1, 96, r="가정법 과거완료는 ‘If + 주어 + had + 과거분사, 주어 + would(n't) have + 과거분사’이다. 조동사 would 뒤에는 동사원형 have가 오고 그 뒤에 과거분사가 온다.",
  n=["wouldn't 뒤에 have + 과거분사(had)를 바르게 썼으므로", "조동사 wouldn't 뒤에는 had가 아니라 동사원형 have가 와야 하므로", "조동사 뒤에 has를 쓸 수 없으므로", "조동사 뒤에 -ing형을 쓸 수 없으므로", "had have라는 형태는 쓸 수 없으므로"],
  st="① if절이 had + 과거분사({0})이므로 과거 사실의 반대를 가정하는 문장이다. 주절은 would have + 과거분사가 된다. → ② 빈칸 앞의 조동사(would not) 뒤에는 동사원형 have가 와야 한다. has, had, having으로 시작하는 보기를 지운다. → ③ have 뒤에 괄호 속 동사({1})의 과거분사를 붙인다. 정답은 {a}.",
  R=("had accepted", "have"), B=("had backed up", "lose"), C=("had left", "miss"), D=("had checked", "get"), E=("had saved", "lose"), F=("had studied", "fail"))

X(1, 97, r="가정법 과거완료는 ‘If + 주어 + had + 과거분사 ~, 주어 + would have + 과거분사 ~’의 형태로 과거 사실의 반대를 가정한다.",
  n=["주절이 would have + 과거분사이면 if절은 spoke가 아니라 had spoken이어야 하므로", "가정법의 주절에 won't를 쓸 수 없으므로", "if절 had spoken, 주절 wouldn't have been으로 가정법 과거완료를 바르게 썼으므로", "if절에 has spoken을 쓸 수 없으므로",
     "had 뒤에는 speak가 아니라 과거분사 spoken이 와야 하므로"],
  st="① 다섯 문장은 같은 내용이고 if절과 주절의 동사 형태만 다르다. → ② 과거 사실의 반대이므로 if절은 had + 과거분사({0}), 주절은 would have + 과거분사({1})여야 한다. → ③ 두 자리가 모두 맞는 문장을 고른다. 정답은 {n}.",
  R=("had spoken", "wouldn't have been"), B=("had read", "would have replied"), C=("had known", "would have told"), D=("had booked", "would have paid"), E=("had brought", "would have entered"), F=("had practiced", "would have won"))

X(1, 98, r="가정법의 if절에 had가 있으면 if를 생략하고 had를 주어 앞으로 보낼 수 있다(Had + 주어 + 과거분사 ~). 과거의 일이 현재에 영향을 주면 주절은 would + 동사원형 ~ now로 쓴다(혼합가정법).",
  n=["쉼표 앞이 평서문 어순이고 주절이 would he로 도치되어 틀렸으므로", "if 없이 Had he inherited ~로 도치하고 주절에 would be ~ now를 바르게 썼으므로", "주어진 had를 쓰지 않았고 두 절을 잇는 말도 없으므로", "주어진 낱말에 없는 If를 썼으므로",
     "주어진 낱말에 없는 If를 쓰고 had도 뺐으므로"],
  st="① 주어진 낱말에 if, had, 쉼표, would, now가 있다. ‘If + 주어 + had + 과거분사 ~, 주어 + would + 동사원형 ~ now’(혼합가정법)의 틀을 떠올린다. → ② if절({0})은 과거의 일, 주절({1})은 지금의 일이다. → ③ 주절을 would have + 과거분사로 바꾸거나 if절의 시제를 바꾼 보기, 어순이 틀린 보기를 지운다. 정답은 {n}.",
  R="① 주어진 낱말에 if가 없고 had와 쉼표가 있다. if를 생략한 도치 문장(Had + 주어 + 과거분사 ~,)을 떠올린다. → ② 쉼표 뒤 주절은 now가 있으므로 would + 동사원형(would be rich now)이다. → ③ 주어진 낱말에 없는 If를 쓴 보기와 어순이 틀린 보기를 지운다. 정답은 {n}.",
  B=("had studied engineering", "would work ~ now"), C=("had accepted the job", "would be living ~ now"), D=("had saved more money", "would own ~ now"), E=("had chosen the other route", "would be there now"), F=("had moved to Seoul", "would live ~ now"))

X(1, 99, r="이미 지난 일에 대해 ‘~했더라면 …했을 텐데’라고 말할 때는 가정법 과거완료(If + had + 과거분사, would have + 과거분사)를 쓴다.",
  n=["가정법 과거는 현재 사실의 반대라 어제의 일에 맞지 않으므로", "가정법의 주절에 will을 쓸 수 없으므로", "주절이 would have + 과거분사이면 if절은 had + 과거분사여야 하므로", "어제 떨어진 일에 대해 가정법 과거완료를 바르게 썼으므로",
     "if절에 have practiced, 주절에 passed를 쓰는 가정법은 없으므로"],
  st="① 앞사람의 말에서 이미 지난 일임을 확인한다: {0}. → ② 지난 일을 반대로 가정하므로 If + had + 과거분사, would have + 과거분사가 필요하다. → ③ if절이나 주절의 형태가 이와 다른 보기를 지운다. 정답은 {n}.",
  R="어제 운전면허 시험에 떨어졌다", B="오늘 아침 비행기를 놓쳤다", C="어제 지원서 내는 것을 잊었다", D="파일을 저장하지 않아 작업을 잃었다", E="어제 시험에 떨어졌다", F="비에 흠뻑 젖었다")

X(1, 100, r="If it had not been for ~(~이 없었더라면)에서 if를 생략하면 Had it not been for ~로 도치한다. 과거 사실의 반대이므로 주절은 would/could have + 과거분사이다.",
  n=["Were it not for ~, could not save는 현재 사실의 반대라 ‘구하지 못했을 것이다’와 시제가 맞지 않으므로", "Had he not have courage는 틀린 형태이므로", "Had it not been for로 도치하고 주절에 could not have saved를 써서 세 조건을 모두 만족하므로",
     "If를 생략하지 않았으므로", "주절이 could not save라 과거 사실의 반대를 나타내지 못하므로"],
  st="① 조건을 형태로 바꾼다. ‘~이 없었더라면’은 If it had not been for ~이고, If를 생략하면 Had it not been for ~가 된다. → ② 우리말의 주절(‘{0}’)은 과거 사실의 반대이므로 would/could have + 과거분사({1})여야 한다. → ③ If나 Without으로 시작하는 보기, 도치 어순이나 주절의 형태가 틀린 보기를 지운다. 정답은 {n}.",
  R=("구하지 못했을 것이다", "could not have saved"), B=("몰랐을 것이다", "would not have known"), C=("지키지 못했을 것이다", "could not have met"), D=("길을 잃었을 것이다", "would have gotten lost"),
  E=("잘못된 선택을 했을 것이다", "would have made"), F=("복구하지 못했을 것이다", "could not have recovered"))
RV(1, 100, "B", v="수정(표기)", why="정답 ③ 확인. <조건>이 ‘If 생략 도치’, ‘축약형 금지’처럼 줄여 쓰여 있고 ‘/’로 이어져 있어 원문항과 표기가 다르다. 사용자가 1-50 B에 준 의견(조건이 원문항에 비해 명시적이지 않음)과 같은 문제다.", fix="원문항처럼 조건을 풀어 쓰고 한 줄에 하나씩")
